float3 getTerrainNormal(FS_INPUT In, ObjectParameters& object)
{
#if 0
    float3 worldNormal;
    worldNormal.xz = tex2DSample(lodNormalMap, samplerBilinearClamp, In.vs.normalMapTexCoords)*2-1; // RG8 stores X,Z
    worldNormal.y = sqrt(max(0.0, 1 - dot(worldNormal.xz, worldNormal.xz)));
    return worldNormal;
#elif defined(USE_VIRTUAL_TEXTURE) && !defined(DEBUG_INFO_TERRAIN_SLOPES)
    return getFacetNormal(getWorldPosition(In), In.vs.screenPosW);
#else
    // yScale is to scale texel units up to heightmap units
    //  = unitsPerPixel / rawHeightmapScale (texel units -> world units -> heightmap units)
    float yScale = object.terrainSizeInvSizeScaleXZScaleY.z / object.terrainSizeInvSizeScaleXZScaleY.w;
    float3 n1 = sampleCompressedHeightmapNormalUV(terrainHeightMap, In.vs.defaultTexCoords, yScale);
#if defined(ENABLE_TERRAIN_DISPLACEMENT)
    int2 imask = tex2DSize(terrainDisplacementMap, 0) - 1;
    if (any((imask & (imask + 1)) != 0)) {
        imask = -1; // not power of two so can't mask
    }
    if (object.terrainDisplacementMapVirtualOffset.z > 0) {
        float3 n2 = sampleDisplacementMapNormalUV(terrainDisplacementMap, In.vs.defaultTexCoords, object.terrainDisplacementMapVirtualSize.x, object.terrainDisplacementMapVirtualOffset.xy, imask, yScale * object.terrainDisplacementMapVirtualSize.y);
        n1 = normalCombinationShear(n1, n2);
    }
#endif
    return n1;
#endif
}

uint getLayerOffsetGroundDetail(ObjectParameters& object)
{
    return floatBitsToUint(object.terrainLayerOffsets.x);
}
uint getLayerOffsetSpray(ObjectParameters& object)
{
    return floatBitsToUint(object.terrainLayerOffsets.y);
}
uint getLayerOffsetFill(ObjectParameters& object)
{
    return floatBitsToUint(object.terrainLayerOffsets.z);
}

void getIndicesAndWeights(FS_INPUT In, ObjectParameters& object, out float3 weights, out uint3 indices, out uint3 lodIndices)
{
    getIndicesAndWeights(lodTypeMap, samplerPointClamp, In.vs.defaultTexCoords, object.terrainPatchOffset.ww, weights, indices, lodIndices);
}

void getDetailIndex(FS_INPUT In, ObjectParameters& object, out uint index, out uint rotation, out uint spray, out uint wetness)
{
    getDetailIndex(terrainDetailMap, In.vs.defaultTexCoords, object.terrainDetailMapVirtualSize.xx, floatBitsToUint(object.terrainDetailShifts), getLayerOffsetGroundDetail(object), index, rotation, spray, wetness);
}

void getDetailIndicesAndWeights(FS_INPUT In, ObjectParameters& object, out float3 weights, out uint3 indices, out uint3 rotations, out uint3 sprays, out uint3 wetnesses)
{
    getDetailIndicesAndWeights(terrainDetailMap, samplerPointClamp, In.vs.defaultTexCoords, object.terrainDetailMapVirtualSize.xx, true, floatBitsToUint(object.terrainDetailShifts), getLayerOffsetGroundDetail(object), weights, indices, rotations, sprays, wetnesses);
}

void getFillIndicesAndWeights(FS_INPUT In, ObjectParameters& object, out float3 weights, out uint3 indices)
{
    getFillIndicesAndWeights(terrainFillMap, samplerPointClamp, In.vs.defaultTexCoords, object.terrainDetailMapVirtualSize.yy, true, getLayerOffsetFill(object), weights, indices);
}

uint quantizeRotation(ObjectParameters& object, uint angle)
{
    int maxRotation = 1 + (floatBitsToInt(object.terrainDetailShifts.y) >> 8);
    int halfRot = maxRotation >> 1;
    return abs((int)angle - halfRot) * 2 < halfRot ? halfRot : 0;
}

float2 applyRot(ObjectParameters& object, float2 uv, int i_angle)
{
    int maxRotation = 1 + (floatBitsToInt(object.terrainDetailShifts.y) >> 8);
    float angle = float(i_angle)/float(maxRotation) * 3.14159;
    float s,c;
    sincos(angle, s, c);
    return float2(uv.x * c - uv.y * s, uv.x * s + uv.y * c);
}

float2 applyNrmRot(ObjectParameters& object, float2 uv, int i_angle)
{
    return applyRot(object, uv * 2 - 1, -i_angle);
}

float processHeightmapPixel(float px, float scale)
{
    return (px * 2 - 1) * scale;
}

MaterialInfo defaultMaterialInfo()
{
    MaterialInfo mat;
    mat.color = 0;
    mat.normal = 0;
    mat.roughness = 1;
    mat.height = 0;
    mat.porosity = 1;
    return mat;
}

MaterialInfo zeroMaterialInfo()
{
    MaterialInfo mat;
    mat.color = 0;
    mat.normal = 0;
    mat.roughness = 0;
    mat.height = 0;
    mat.porosity = 0;
    return mat;
}

void blendMaterialLayerWithWeight(inout MaterialInfo acc, MaterialInfo mat, float weight)
{
    acc.color += mat.color * weight;
    acc.normal += mat.normal * weight;
    acc.roughness += mat.roughness * weight;
    acc.height += mat.height * weight;
    acc.porosity += mat.porosity * weight;
}

void blendMaterialLayerWithAlpha(inout MaterialInfo acc, MaterialInfo mat, float alpha)
{
    acc.color = lerp(acc.color, mat.color, alpha);
    acc.normal = lerp(acc.normal, mat.normal, alpha);
    acc.roughness = lerp(acc.roughness, mat.roughness, alpha);
    acc.height = lerp(acc.height, mat.height, alpha);
    acc.porosity = lerp(acc.porosity, mat.porosity, alpha);
}

TexcoordInfo newTexcoordInfo()
{
    TexcoordInfo tc;
    tc.uv = 0;
    tc.ddx_uv = 0;
    tc.ddy_uv = 0;
    tc.scale = 1;
    return tc;
}

TexcoordInfo scaleOffsetTexcoords(TexcoordInfo tc, float scale, float2 offset)
{
    TexcoordInfo tcout;
    tcout.uv = tc.uv * scale + offset;
    tcout.ddx_uv = tc.ddx_uv * scale;
    tcout.ddy_uv = tc.ddy_uv * scale;
    tcout.scale = tc.scale * scale;
    return tcout;
}

TexcoordInfo applyRot(ObjectParameters& object, TexcoordInfo tc, int i_angle)
{
    TexcoordInfo tcout;
    tcout.uv = applyRot(object, tc.uv, i_angle);
    tcout.ddx_uv = applyRot(object, tc.ddx_uv, i_angle);
    tcout.ddy_uv = applyRot(object, tc.ddy_uv, i_angle);
    tcout.scale = tc.scale;
    return tcout;
}

float getManureLerpFactor(float alpha, float height)
{
    // Height is in centered around 0, -1,1 range
    float factor = saturate(1 - pow(max(0.0, height * 1.375 - 0.375), 1));
    return lerp(factor, alpha, 1 - factor);
}

void processSpray(inout MaterialInfo mat, FS_INPUT In, FS_GLOBALS globals, PerInstanceParameters& instance, ObjectParameters& object, uint sprayType, TexcoordInfo texcoords, float height)
{
    if (sprayType > 0) {
        uint index = sprayType - 1 + getLayerOffsetSpray(object);

        float4 params = bufferFetch(layerParameters, index * 2);

        TexcoordInfo tc = scaleOffsetTexcoords(texcoords, params.x, 0.0);

        float4 sprayTexel = tex2DSampleGrad(baseMap, ALBEDO_MAP_SAMPLER, tc.uv, index, tc.ddx_uv, tc.ddy_uv);
        float lerpFactor = sprayTexel.w;

        // Apply special behavior for liquid manure (sprayType 3) (not needed on mobile since we only have fertilizer (sprayType 1)
        #if !defined(MOBILE_VERSION)
            lerpFactor = (sprayType != 3) ? lerpFactor : getManureLerpFactor(lerpFactor, height);
            mat.roughness = (sprayType != 3) ? mat.roughness : lerp(0.5, 1, 1 - lerpFactor);
        #endif
        mat.color = lerp(mat.color, sprayTexel.rgb, lerpFactor);
    }
}

void processFieldWetness(inout MaterialInfo mat, FS_INPUT In, FS_GLOBALS globals, PerInstanceParameters& instance, ObjectParameters& object, uint wetness)
{
    if (wetness == 1) {
        mat.color = getAdjustedWetDiffuseColor(In, globals, instance, object, mat.color, 0.0, mat.porosity, 1.0);
        mat.roughness = getAdjustedWetRoughness(In, globals, instance, object, mat.roughness, 0.0, mat.porosity, 1.0);
        mat.porosity = 0;   // we have applied wetness already so we don't want to allow wetness from rain; porosity = 0 does this (mostly; diffuse adjustment is disabled but roughness adjustment happens twice)
    }
}

bool sprayIsFlat(uint sprayType)
{
#if defined(MOBILE_VERSION)
    // The mobile version only has fertilizer (sprayType 1)
    return true;
#else
    return (sprayType == 5) || (sprayType == 6);
#endif
}

#if !defined(USE_VIRTUAL_TEXTURE)
void readMaterialLayerColor(FS_INPUT In, ObjectParameters& object, TexcoordInfo texcoords, uint index, inout MaterialInfo mat, out TexcoordInfo tc, out float contrast, out float texAlpha)
{
    float4 params = bufferFetch(layerParameters, index * 2);
    contrast = params.y;

    tc = scaleOffsetTexcoords(texcoords, params.x, 0.0);

#if defined(ALBEDO_MAP)
    if (In.vs.terrainDistanceWeight < 1) {
        float4 colMap = tex2DSampleGrad(baseMap, ALBEDO_MAP_SAMPLER, tc.uv, index, tc.ddx_uv, tc.ddy_uv);
        mat.color = colMap.rgb;
        texAlpha = colMap.a;
    } else {
        texAlpha = 1;
    }
    if (In.vs.terrainDistanceWeight > 0) {
        float scale = 0.1;
        float4 colMap = tex2DSampleGrad(baseMap, ALBEDO_MAP_SAMPLER, texcoords.uv * params.x * scale, index, tc.ddx_uv * scale, tc.ddy_uv * scale);
        mat.color = lerp(mat.color, colMap.rgb, saturate(In.vs.terrainDistanceWeight));
        texAlpha = lerp(texAlpha, colMap.a, saturate(In.vs.terrainDistanceWeight));
    }
#endif
}

void readMaterialLayerRest(FS_INPUT In, ObjectParameters& object, uint index, inout MaterialInfo mat, TexcoordInfo tc)
{
#if defined(TERRAIN_NORMAL_MAPPING)
    float3 nrmMap = tex2DSampleGrad(normalMap, NORMAL_MAP_SAMPLER, tc.uv, index, tc.ddx_uv, tc.ddy_uv).xyz;
    mat.normal = nrmMap.xy * 2 - 1;
    mat.roughness = 1 - nrmMap.z;

#if TERRAIN_QUALITY > 1 && defined(PARALLAX_MAP)
    float htMap = tex2DSampleGrad(HEIGHT_MAP_TEXTURE, HEIGHT_MAP_SAMPLER, tc.uv, index, tc.ddx_uv, tc.ddy_uv).HEIGHT_MAP_CHANNEL;

    // heights must be scaled down if the repeat is larger than the min repeat, as the UVs are now smaller while the height/UV ratio is fixed
    mat.height = processHeightmapPixel(htMap, VT_PARALLAX_MIN_REPEAT / tc.scale);
#endif
#endif

    float4 params = bufferFetch(layerParameters, index * 2 + 1);
    mat.porosity = params.z + mat.roughness * params.w;
}

void readMaterialDetailLayerColor(FS_INPUT In, ObjectParameters& object, TexcoordInfo texcoords, uint index, uint rot, uint spray, inout MaterialInfo mat, out TexcoordInfo tc, out float contrast, out float texAlpha, out float noiseScale, out float noiseSharp, out uint customLayerPlusOne)
{
    if (index != 0) {
        float4 params0 = bufferFetch(layerParameters, (index - 1) * 2);
        contrast = params0.y;
        noiseScale = params0.z;
        noiseSharp = 0.5;//params0.w;
        customLayerPlusOne = uint(params0.w);
        if (customLayerPlusOne != 0) {
            customLayerPlusOne += getLayerOffsetGroundDetail(object);
        }

        tc = applyRot(object, scaleOffsetTexcoords(texcoords, params0.x, 0.5), int(rot));

#if defined(ALBEDO_MAP)
        float4 colMap = tex2DSampleGrad(baseMap, ALBEDO_MAP_SAMPLER, tc.uv, index - 1, tc.ddx_uv, tc.ddy_uv);
        mat.color = colMap.rgb;
        texAlpha = colMap.a;
#endif
    } else {
        tc = texcoords;
        texAlpha = 0.7;
        contrast = 0.5;
        noiseScale = 0.5;
        noiseSharp = 0.25;
        customLayerPlusOne = 0;
    }
}

void readCustomLayer(FS_INPUT In, ObjectParameters& object, TexcoordInfo texcoords, uint index, uint rot, float customBlendFactor, inout MaterialInfo mat, out float blendFactor)
{
    if ((index != 0) && (customBlendFactor > 0)) {
        float4 params0 = bufferFetch(layerParameters, (index - 1) * 2);

        TexcoordInfo tc = applyRot(object, scaleOffsetTexcoords(texcoords, params0.x, 0.5), int(rot));

#if defined(ALBEDO_MAP)
        float4 colMap = tex2DSampleGrad(baseMap, ALBEDO_MAP_SAMPLER, tc.uv, index - 1, tc.ddx_uv, tc.ddy_uv);
        mat.color = colMap.rgb;
#endif

#if defined(TERRAIN_NORMAL_MAPPING)
        float3 nrmMap = tex2DSampleGrad(normalMap, NORMAL_MAP_SAMPLER, tc.uv, index - 1, tc.ddx_uv, tc.ddy_uv).xyz;
        mat.normal = nrmMap.xy * 2 - 1;
        mat.roughness = 1 - nrmMap.z;

#if TERRAIN_QUALITY > 1 && defined(PARALLAX_MAP)
        float htMap = tex2DSampleGrad(HEIGHT_MAP_TEXTURE, HEIGHT_MAP_SAMPLER, tc.uv, index - 1, tc.ddx_uv, tc.ddy_uv).HEIGHT_MAP_CHANNEL;
        mat.height = processHeightmapPixel(htMap, VT_PARALLAX_MIN_REPEAT / tc.scale);
#endif
#endif

        float4 params1 = bufferFetch(layerParameters, (index - 1) * 2 + 1);
        mat.porosity = params1.z + mat.roughness * params1.w;

        blendFactor = customBlendFactor;
    } else {
        blendFactor = 0;
    }
}

void readMaterialDetailLayerRest(FS_INPUT In, FS_GLOBALS globals, PerInstanceParameters& instance, ObjectParameters& object, uint index, uint rot, uint spray, uint wetness, MaterialInfo customMat, float customBlendFactor, inout MaterialInfo mat, TexcoordInfo tc, TexcoordInfo texcoords)
{
    if (customBlendFactor > 0) {
        mat.color = lerp(mat.color, customMat.color, customBlendFactor);
    }

#if defined(TERRAIN_NORMAL_MAPPING)
    float3 nrmMap = tex2DSampleGrad(normalMap, NORMAL_MAP_SAMPLER, tc.uv, index - 1, tc.ddx_uv, tc.ddy_uv).xyz;
    mat.normal = applyNrmRot(object, nrmMap.xy, int(rot));
    mat.roughness = 1 - nrmMap.z;
    if (customBlendFactor > 0) {
        mat.normal = lerp(mat.normal, customMat.normal, customBlendFactor);
        mat.roughness = lerp(mat.roughness, customMat.roughness, customBlendFactor);
    }

#if TERRAIN_QUALITY > 1 && defined(PARALLAX_MAP)
    float htMap = tex2DSampleGrad(HEIGHT_MAP_TEXTURE, HEIGHT_MAP_SAMPLER, tc.uv, index - 1, tc.ddx_uv, tc.ddy_uv).HEIGHT_MAP_CHANNEL;
    mat.height = processHeightmapPixel(htMap, VT_PARALLAX_MIN_REPEAT / tc.scale);
    if (customBlendFactor > 0) {
        mat.height = lerp(mat.height, customMat.height, customBlendFactor);
    }

    processSpray(mat, In, globals, instance, object, spray, texcoords, htMap);
#endif
#endif

    processFieldWetness(mat, In, globals, instance, object, wetness);

    float4 params1 = bufferFetch(layerParameters, (index - 1) * 2 + 1);
    mat.porosity = params1.z + mat.roughness * params1.w;
    if (customBlendFactor > 0) {
        mat.porosity = lerp(mat.porosity, customMat.porosity, customBlendFactor);
    }
}

void readMaterialFillLayerColor(FS_INPUT In, ObjectParameters& object, TexcoordInfo texcoords, uint index, inout MaterialInfo mat, out TexcoordInfo tc, out float contrast, out float texAlpha, out float noiseScale, out float noiseSharp)
{
    if (index != 0) {
        float4 params0 = bufferFetch(layerParameters, (index - 1) * 2);
        contrast = params0.y;
        noiseScale = params0.z;
        noiseSharp = 0.5f;//params0.w;

        tc = scaleOffsetTexcoords(texcoords, params0.x, 0);

#if defined(ALBEDO_MAP)
        float4 colMap = tex2DSampleGrad(baseMap, ALBEDO_MAP_SAMPLER, tc.uv, index - 1, tc.ddx_uv, tc.ddy_uv);
        mat.color = colMap.rgb;
        texAlpha = colMap.a;
#endif
    } else {
        tc = texcoords;
        texAlpha = 1;
        contrast = 0.5;
        noiseScale = 0.5;
        noiseSharp = 0.25;
    }
}

void readMaterialFillLayerRest(FS_INPUT In, ObjectParameters& object, uint index, inout MaterialInfo mat, TexcoordInfo tc)
{
#if defined(TERRAIN_NORMAL_MAPPING)
    float3 nrmMap = tex2DSampleGrad(normalMap, NORMAL_MAP_SAMPLER, tc.uv, index - 1, tc.ddx_uv, tc.ddy_uv).xyz;
    mat.normal = nrmMap.xy * 2 - 1;
    mat.roughness = 1 - nrmMap.z;

#if TERRAIN_QUALITY > 1 && defined(PARALLAX_MAP)
    float htMap = tex2DSampleGrad(HEIGHT_MAP_TEXTURE, HEIGHT_MAP_SAMPLER, tc.uv, index - 1, tc.ddx_uv, tc.ddy_uv).HEIGHT_MAP_CHANNEL;
    mat.height = processHeightmapPixel(htMap, VT_PARALLAX_MIN_REPEAT / tc.scale) + 0.025;   // add a slight offset so the piles appear above ground level even when blending out
#endif
#endif

    float4 params1 = bufferFetch(layerParameters, (index - 1) * 2 + 1);
    mat.porosity = params1.z + mat.roughness * params1.w;
}

void getBlendedColorAndNormal(inout FS_INPUT In, FS_GLOBALS globals, PerInstanceParameters& instance, ObjectParameters& object, out MaterialInfo material, out ParallaxInfo parallax, out TexcoordInfo texcoords, out float dirtValue, out float fillDepthValue)
{
    material = zeroMaterialInfo();
    float accumulatedAlpha = 0;

    fillDepthValue = object.terrainDepthValues.x;

    parallax.index = 0;
    parallax.rot = 0;
    parallax.spray = 0;
    parallax.weight = 0;

    texcoords.uv = In.vs.defaultTexCoords;
    texcoords.ddx_uv = ddx(In.vs.defaultTexCoords);
    texcoords.ddy_uv = ddy(In.vs.defaultTexCoords);
    texcoords.scale = 1;

    float2 dirtUV = In.vs.defaultTexCoords * 8.2;
    dirtValue = (tex2DSample(noiseMap, samplerBilinearWrap, dirtUV).x - 0.5) * 0.5 + 1;

#if defined(ENABLE_TERRAIN_DISPLACEMENT)
    int2 imask = tex2DSize(terrainDisplacementMap, 0) - 1;
    if (any((imask & (imask + 1)) != 0)) {
        imask = -1; // not power of two so can't mask
    }
    float customBlendFactor = sampleDisplacementCustomFlagUV(terrainDisplacementMap, In.vs.defaultTexCoords, object.terrainDisplacementMapVirtualSize.x, object.terrainDisplacementMapVirtualOffset.xy, imask);
#else
    float customBlendFactor = 0;
#endif

    //
    // apply distance LOD
    //
    float3 linearWeights;
    uint3 indices;
    uint3 lodIndices;
    getIndicesAndWeights(In, object, linearWeights, indices, lodIndices);

#if defined(ENABLE_DISTANCE_LOD)
    // generate dynamic LOD weights now so we can early-out
    float3 lodWeights = linearWeights * float3(lodIndices < 255);
    float lodAlpha = (lodWeights.x + lodWeights.y + lodWeights.z) * saturate(In.vs.terrainLodMapWeight1);
    if (lodAlpha > 0.0001) {
        uint index, rotation, spray, wetness;
        getDetailIndex(In, object, index, rotation, spray, wetness);

        TexcoordInfo dtc = scaleOffsetTexcoords(texcoords, 16, 0);
        if (index != 0) {
            rotation = quantizeRotation(object, rotation);
            dtc = applyRot(object, dtc, rotation);
        }

        float4 lodColorRoughness = tex2DSample(lodDiffuseMap, standardMaterialSampler, dtc.uv, lodIndices.x) * lodWeights.x +
                                   tex2DSample(lodDiffuseMap, standardMaterialSampler, dtc.uv, lodIndices.y) * lodWeights.y +
                                   tex2DSample(lodDiffuseMap, standardMaterialSampler, dtc.uv, lodIndices.z) * lodWeights.z;
        MaterialInfo lodMaterial = defaultMaterialInfo();
        lodMaterial.color = lodColorRoughness.rgb;
        lodMaterial.roughness = (1 - lodColorRoughness.w);

        blendMaterialLayerWithWeight(material, lodMaterial, lodAlpha);
        accumulatedAlpha += lodAlpha;
    }
    if (accumulatedAlpha >= 0.9999) {
        return;
    }
#endif

    //
    // apply terrain fill
    //
#if defined(ENABLE_TERRAIN_FILL)
    float fillRampDown = 1 - saturate(In.vs.terrainLodMapWeight0);
    if (fillRampDown > 0) {
        float3 linearWeights;
        uint3 indices;
        getFillIndicesAndWeights(In, object, linearWeights, indices);

        bool3 activeIndices = (indices != 0);
        if (any(activeIndices)) {
            float3 texAlpha;
            float3 contrast;
            float3 noiseScale;
            float3 noiseSharp;
            TexcoordInfo tc0;
            TexcoordInfo tc1;
            TexcoordInfo tc2;
            MaterialInfo mat0 = defaultMaterialInfo();
            MaterialInfo mat1 = defaultMaterialInfo();
            MaterialInfo mat2 = defaultMaterialInfo();

            readMaterialFillLayerColor(In, object, texcoords, indices.x, mat0, tc0, contrast.x, texAlpha.x, noiseScale.x, noiseSharp.x);
            readMaterialFillLayerColor(In, object, texcoords, indices.y, mat1, tc1, contrast.y, texAlpha.y, noiseScale.y, noiseSharp.y);
            readMaterialFillLayerColor(In, object, texcoords, indices.z, mat2, tc2, contrast.z, texAlpha.z, noiseScale.z, noiseSharp.z);

            // compute non-linear weights, normalized to a sum of 1
            linearWeights *= float3(activeIndices);
            float3 weights;
            getBlendWeights(linearWeights, texAlpha, contrast, weights);

            // compute inter-layer blend factor
            float layerWeight = dot(linearWeights, 1);
            if (!all(activeIndices)) {
                float noiseValue = (tex2DSample(noiseMap, samplerBilinearWrap, texcoords.uv * VT_PARALLAX_MIN_REPEAT).x - 0.5) * 2;
                layerWeight += noiseValue * dot(noiseScale, weights);

                float heightAdjust = dot(float3(mat0.height, mat1.height, mat2.height), weights);
                layerWeight += heightAdjust * 0.5;

                float sharpnessValue = max(0.01, dot(noiseSharp, weights));
                float midpointValue = 0.5;

                layerWeight = saturate((-1 + layerWeight + midpointValue*(1 + sharpnessValue))/sharpnessValue);
            }

            // apply rampdown and deweighting
            layerWeight *= fillRampDown;
            layerWeight *= 1 - accumulatedAlpha;
            weights *= layerWeight;

            if (weights.x > 0.0001) {
                readMaterialFillLayerRest(In, object, indices.x, mat0, tc0);
                blendMaterialLayerWithWeight(material, mat0, weights.x);
            }
            if (weights.y > 0.0001) {
                readMaterialFillLayerRest(In, object, indices.y, mat1, tc1);
                blendMaterialLayerWithWeight(material, mat1, weights.y);
            }
            if (weights.z > 0.0001) {
                readMaterialFillLayerRest(In, object, indices.z, mat2, tc2);
                blendMaterialLayerWithWeight(material, mat2, weights.z);
            }

            accumulatedAlpha += layerWeight;

            if (layerWeight > 0.5) {
                fillDepthValue = max(fillDepthValue, object.terrainDepthValues.z);
            }
        }
    }
#endif

    //
    // apply terrain detail
    //
#if defined(ENABLE_TERRAIN_DETAIL)
    float detailRampDown = 1 - saturate(In.vs.terrainLodMapWeight0);
    bool parallaxInDetail = false;
    if (detailRampDown > 0) {
        float3 linearWeights;
        uint3 indices, rotations, sprays, wetnesses;
        getDetailIndicesAndWeights(In, object, linearWeights, indices, rotations, sprays, wetnesses);

        bool3 activeIndices = (indices != 0);
        if (any(activeIndices)) {
            float3 texAlpha;
            float3 contrast;
            float3 noiseScale;
            float3 noiseSharp;
            uint3 customLayerPlusOne;
            TexcoordInfo tc0;
            TexcoordInfo tc1;
            TexcoordInfo tc2;
            MaterialInfo mat0 = defaultMaterialInfo();
            MaterialInfo mat1 = defaultMaterialInfo();
            MaterialInfo mat2 = defaultMaterialInfo();

            readMaterialDetailLayerColor(In, object, texcoords, indices.x, rotations.x, sprays.x, mat0, tc0, contrast.x, texAlpha.x, noiseScale.x, noiseSharp.x, customLayerPlusOne.x);
            readMaterialDetailLayerColor(In, object, texcoords, indices.y, rotations.y, sprays.y, mat1, tc1, contrast.y, texAlpha.y, noiseScale.y, noiseSharp.y, customLayerPlusOne.y);
            readMaterialDetailLayerColor(In, object, texcoords, indices.z, rotations.z, sprays.z, mat2, tc2, contrast.z, texAlpha.z, noiseScale.z, noiseSharp.z, customLayerPlusOne.z);

            // compute non-linear weights, normalized to a sum of 1
            linearWeights *= float3(activeIndices);
            float3 weights;
            getBlendWeights(linearWeights, texAlpha, contrast, weights);

            // compute inter-layer blend factor
            float layerWeight = dot(linearWeights, 1);
            if (!all(activeIndices)) {
                float noiseValue = (tex2DSample(noiseMap, samplerBilinearWrap, texcoords.uv * VT_PARALLAX_MIN_REPEAT).x - 0.5) * 2;
                layerWeight += noiseValue * dot(noiseScale, weights);

                float sharpnessValue = max(0.01, dot(noiseSharp, weights));
                float midpointValue = 0.5;

                layerWeight = saturate((-1 + layerWeight + midpointValue*(1 + sharpnessValue))/sharpnessValue);
            }

            // apply rampdown and deweighting
            layerWeight *= detailRampDown;
            layerWeight *= 1 - accumulatedAlpha;
            weights *= layerWeight;

            // remove parallax channel if layer weight is at least 0.5
#if defined(TERRAIN_NORMAL_MAPPING) && TERRAIN_QUALITY > 1 && defined(PARALLAX_MAP)
            if ((In.vs.terrainParallaxWeight > 0) && (layerWeight > 0.5)) {
                parallaxInDetail = true;
                float maxWeight = max(weights.x, max(weights.y, weights.z));

                if (maxWeight == weights.x) {
                    parallax.index = indices.x - 1;
                    parallax.rot = rotations.x;
                    parallax.spray = sprays.x;
                    texcoords = tc0;
                } else if (maxWeight == weights.y) {
                    parallax.index = indices.y - 1;
                    parallax.rot = rotations.y;
                    parallax.spray = sprays.y;
                    texcoords = tc1;
                } else {
                    parallax.index = indices.z - 1;
                    parallax.rot = rotations.z;
                    parallax.spray = sprays.z;
                    texcoords = tc2;
                }

                float3 match = float3(256 * parallax.index + 32 * parallax.spray + parallax.rot == 256 * (indices - 1) + 32 * sprays + rotations);

                match *= saturate(In.vs.terrainParallaxWeight);

                parallax.weight = dot(weights, match);
                weights *= (1 - match);
            }
#endif

            float3 customBlend = 0;
            MaterialInfo customMat0 = defaultMaterialInfo();
            MaterialInfo customMat1 = defaultMaterialInfo();
            MaterialInfo customMat2 = defaultMaterialInfo();

            if (weights.x > 0.0001) {
                readCustomLayer(In, object, texcoords, customLayerPlusOne.x, rotations.x, customBlendFactor, customMat0, customBlend.x);
                readMaterialDetailLayerRest(In, globals, instance, object, indices.x, rotations.x, sprays.x, wetnesses.x, customMat0, customBlend.x, mat0, tc0, texcoords);
                blendMaterialLayerWithWeight(material, mat0, weights.x);
            }
            if (weights.y > 0.0001) {
                readCustomLayer(In, object, texcoords, customLayerPlusOne.y, rotations.y, customBlendFactor, customMat1, customBlend.y);
                readMaterialDetailLayerRest(In, globals, instance, object, indices.y, rotations.y, sprays.y, wetnesses.y, customMat1, customBlend.y, mat1, tc1, texcoords);
                blendMaterialLayerWithWeight(material, mat1, weights.y);
            }
            if (weights.z > 0.0001) {
                readCustomLayer(In, object, texcoords, customLayerPlusOne.z, rotations.z, customBlendFactor, customMat2, customBlend.z);
                readMaterialDetailLayerRest(In, globals, instance, object, indices.z, rotations.z, sprays.z, wetnesses.z, customMat2, customBlend.z, mat2, tc2, texcoords);
                blendMaterialLayerWithWeight(material, mat2, weights.z);
            }

            accumulatedAlpha += layerWeight;

            if (layerWeight > 0.5) {
                fillDepthValue = max(fillDepthValue, object.terrainDepthValues.y);
            }
        }
    }
#endif

    //
    // apply base terrain
    //
    if (accumulatedAlpha < 0.9999) {
#if defined(ENABLE_TERRAIN_BASE)
        float3 texAlpha;
        float3 contrast;
        TexcoordInfo tc0;
        TexcoordInfo tc1;
        TexcoordInfo tc2;
        MaterialInfo mat0 = defaultMaterialInfo();
        MaterialInfo mat1 = defaultMaterialInfo();
        MaterialInfo mat2 = defaultMaterialInfo();

        readMaterialLayerColor(In, object, texcoords, indices.x, mat0, tc0, contrast.x, texAlpha.x);
        readMaterialLayerColor(In, object, texcoords, indices.y, mat1, tc1, contrast.y, texAlpha.y);
        readMaterialLayerColor(In, object, texcoords, indices.z, mat2, tc2, contrast.z, texAlpha.z);

        // compute non-linear weights, normalized to a sum of 1
        float3 weights;
        getBlendWeights(linearWeights, texAlpha, contrast, weights);

        weights *= (1 - accumulatedAlpha);

        // remove parallax channel if not already done
#if defined(TERRAIN_NORMAL_MAPPING) && TERRAIN_QUALITY > 1 && defined(PARALLAX_MAP)
        if ((In.vs.terrainParallaxWeight > 0) && !parallaxInDetail) {
            float maxWeight = max(weights.x, max(weights.y, weights.z));

            if (maxWeight == weights.x) {
                parallax.index = indices.x;
                texcoords = tc0;
            } else if (maxWeight == weights.y) {
                parallax.index = indices.y;
                texcoords = tc1;
            } else {
                parallax.index = indices.z;
                texcoords = tc2;
            }

            float3 match = float3(parallax.index == indices);

            match *= saturate(In.vs.terrainParallaxWeight);

            parallax.weight = dot(weights, match);
            weights *= (1 - match);
        }
#endif

        if (weights.x > 0.0001) {
            readMaterialLayerRest(In, object, indices.x, mat0, tc0);
            blendMaterialLayerWithWeight(material, mat0, weights.x);
        }
        if (weights.y > 0.0001) {
            readMaterialLayerRest(In, object, indices.y, mat1, tc1);
            blendMaterialLayerWithWeight(material, mat1, weights.y);
        }
        if (weights.z > 0.0001) {
            readMaterialLayerRest(In, object, indices.z, mat2, tc2);
            blendMaterialLayerWithWeight(material, mat2, weights.z);
        }
#else
        MaterialInfo greyMat = defaultMaterialInfo();
        greyMat.color = float3(0.5, 0.5, 0.5);
        blendMaterialLayerWithWeight(material, greyMat, 1 - accumulatedAlpha);
#endif
    }
}
